        key_tuple = tuple(current_key_values)

        if key_tuple not in seen_keys:
            # New unique key found
            seen_keys[key_tuple] = record.copy()
            result.append(seen_keys[key_tuple])
        else:
            # Key already exists, handle policy
            existing_record = seen_keys[key_tuple]

            if policy == "first":
                pass  # Keep the first one we stored
            elif policy == "last":
                seen_keys[key_tuple] = record.copy()
                result[-1] = seen_keys[key_tuple] # This is wrong because result order depends on first appearance
