    n = len(old)
    m = len(new)
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n):
        for j in range(m):
            if old[i] == new[j]:
                dp[i+1][j+1] = dp[i][j] + 1
            else:
                dp[i+1][j+1] = max(dp[i][j], dp[i+1][j])

    lcs_old = []
    lcs_new = []
    i, j = n, m
    while i > 0 and j > 0:
        if old[i-1] == new[j-1]:
            lcs_old.append(i-1)
            lcs_new.append(j-1)
            i -= 1
            j -= 1
        elif dp[i][j] == dp[i][j-1]:
            j -= 1
        else:
            i -= 1
    lcs_old.reverse()
    lcs_new.reverse()

    anchors = list(zip(lcs_old, lcs_new))
    hunks = []
    prev_i = 0
    prev_j = 0
    for i_idx, j_idx in anchors:
        if i_idx > prev_i or j_idx > prev_j:
            hunks.append({
